    public static function registered_menus() : array {
		return apply_filters( 'zencommunity/registered_menus', [
			'primary_menu' => 'Primary menu', 
			'top_menu' => 'Top menu', 
			'profile_menu' => 'Profile menu',
			'sidebar_bottom_links' => 'Sidebar Bottom Links',
		] );
	}
    public static function get_all() : array {
        $menus = [];
        foreach ( static::registered_menus() as $key => $label ) {
            $menus[$key] = [
                'label' => $label,
                'items' => ( new static( $key ) )->get_menu(),
            ];
        }
        return $menus;
    }

	/**
	 * Every item (default + link) fully normalized — status/roles overrides
	 * merged in, icon fallback applied — but NOT filtered for the current
	 * viewer. Used both by get_menu() (which filters this for the viewer) and
	 * by find_item() (which must NOT filter: a management action like
	 * creating or restricting an item is performed by an admin who may not
	 * personally match the very roles they just set, and the REST response
	 * confirming that action shouldn't come back empty because of it).
	 */
	private function get_normalized_items() : array {
        $this->default_items_map = apply_filters( "zencommunity/menu", $this->default_items_map );
		$default_items = $this->default_items_map[ $this->menu_key ] ?? [];
        $default_items = $this->default_items_map[ $this->menu_key ] = apply_filters( "zencommunity/menu/{$this->menu_key}", $default_items );

		$all_menus    = get_option( self::BASE_OPTION_KEY, [] );
		$dynamic_menu = $all_menus[ $this->menu_key ]['items'] ?? [];

		$link_items = array_filter( $dynamic_menu, fn( $item ) => ( $item['type'] ?? '' ) === 'link' );

		// Merge default and link
		$merged = array_merge( $default_items, $link_items );

		// "Follower"/"Following" were merged into the single "Connection" tab.
		// Some sites still carry these as leftover default- or link-shaped
		// items from before that merge; drop them here so neither the admin
		// Menu Settings table nor the frontend ever sees them again, without
		// having to migrate/delete the underlying option data.
		if ( 'profile_menu' === $this->menu_key ) {
			$merged = array_values( array_filter( $merged, function ( $item ) {
				$label = strtolower( trim( $item['label'] ?? $item['title'] ?? '' ) );
				return ! in_array( $label, [ 'follower', 'following' ], true );
			} ) );
		}

		// Get activation status and role restrictions from DB
		$active_status = get_option( self::ACTIVE_STATUS_OPTION, [] );
		$roles_option  = get_option( self::ROLES_OPTION, [] );

		// Normalize menu structure
		foreach ( $merged as &$item ) {
			$id               = $item['id'] ?? '';
			$item['status']   = $active_status[ $id ] ?? true;
			$item['type']     = $item['type'] ?? 'default';
			$item['label']    = $item['label'] ?? $item['title'] ?? '';
			unset( $item['title'] ); // Cleanup legacy key if exists

			// A role override (set via the "Restrict roles" action, works for
			// default items too) wins over roles baked into the item itself
			// (only ever set on link items, via add_link_item/update_link_item).
			if ( array_key_exists( $id, $roles_option ) ) {
				$item['roles'] = $roles_option[ $id ];
			}

			$item['icon'] = $item['icon'] ?? [
				'type' => 'emoji',
				'src'  => '❓',
			];
		}

		return $merged;
	}

	public function get_menu() : array {
		// Visibility (status/roles) must always apply, not only once an admin has
		// reordered the menu — filter first, then reorder whatever's left.
		$merged = $this->filter_visible_items( $this->get_normalized_items() );

		$order_option = get_option( 'zenc_' . $this->menu_key . self::ORDER_OPTION_SUFFIX, [] );
		if ( ! empty( $order_option ) && is_array( $order_option ) ) {
			$merged = $this->reorder_by_ids( $merged, $order_option );
		}

		return $merged;
	}

	private function filter_visible_items( array $menu ) : array {
		$visible = [];
		foreach ( $menu as $item ) {
			if ( ! ( $item['show'] ?? true ) ) {
				continue;
			}

			// No manage_options bypass here, unlike status below: if an item is
			// role-restricted, the current user must actually hold one of the
			// listed roles to see it — admins included. An admin who wants to
			// keep seeing their own restricted items needs "wp:administrator"
			// (or another role they hold) in the selection, same as anyone else.
			if (
				! empty( $item['roles'] ?? '' ) &&
				is_array( $item['roles'] ) &&
				! RoleManager::user_matches_menu_roles( get_current_user_id(), $item['roles'] )
			) {
				continue;
			}

			if (
				! current_user_can( 'manage_options' ) &&
				false === boolval( $item['status'] ?? '' )
			) {
				continue;
			}

			$visible[] = $item;
		}
		return $visible;
	}

	private function reorder_by_ids( array $menu, array $ordered_ids ): array {
		$menu_by_id = [];
		foreach ( $menu as $item ) {
			$menu_by_id[ $item['id'] ] = $item;
		}

		$new_menu = [];
		foreach ( $ordered_ids as $id ) {
			if ( isset( $menu_by_id[ $id ] ) ) {
				$new_menu[] = $menu_by_id[ $id ];
				unset( $menu_by_id[ $id ] );
			}
		}
		return array_merge( $new_menu, array_values( $menu_by_id ) );
	}

	public function save_order( array $ordered_ids ) : bool {
		return update_option( 'zenc_' . $this->menu_key . self::ORDER_OPTION_SUFFIX, $ordered_ids );
	}

	public function update_is_active( string $item_id, bool $status ) : bool {
		$active_status           = get_option( self::ACTIVE_STATUS_OPTION, [] );
		$active_status[ $item_id ] = $status;
		return update_option( self::ACTIVE_STATUS_OPTION, $active_status );
	}

	/**
	 * Sets (or clears, when $roles is empty) the visibility-role restriction for
	 * any menu item, default or link, the same way update_is_active() does for
	 * status. This is the mechanism that lets default items (Feeds/Groups/...)
	 * be role-restricted despite not being otherwise editable.
	 */
	public function update_item_roles( string $item_id, ?array $roles ) : bool {
		if ( empty( $roles ) ) {
			$roles = null;
		}
		$roles_option             = get_option( self::ROLES_OPTION, [] );
		$roles_option[ $item_id ] = $roles;
		return update_option( self::ROLES_OPTION, $roles_option );
	}

	/**
	 * Full, normalized representation of one item (status/roles overrides
	 * merged in, icon fallback applied) — used to hand callers something they
	 * can push straight into client state, instead of the id-less/status-less
	 * raw item they submitted. Deliberately reads get_normalized_items(), not
	 * get_menu(): this confirms what was saved, regardless of whether the
	 * acting admin happens to match the roles they just set.
	 */
	private function find_item( string $item_id ) : array {
		foreach ( $this->get_normalized_items() as $item ) {
			if ( ( $item['id'] ?? '' ) === $item_id ) {
				return $item;
			}
		}
		return [];
	}

	public function add_link_item( array $item ) : array {
		if (
			empty( $item['label'] ) ||
			empty( $item['url'] )
		) {
			throw new ZencommunityException( esc_html( __( "Menu labe, url is required.", 'zencommunity' ) ), 422 );
		}

		if ( empty( $item['id'] ) ) {
			$item['id'] = uniqid( 'menu' );
		}

		if ( empty( $item['roles'] ?? '' ) ) {
			$item['roles'] = null;
		}

		$item['type'] = 'link';

		$all_menus = get_option( self::BASE_OPTION_KEY, [] );
		if ( ! isset( $all_menus[ $this->menu_key ] ) ) {
			$all_menus[ $this->menu_key ] = [ 'items' => [] ];
		}

		$existing_ids = array_column( $this->get_menu(), 'id' );
		if ( in_array( $item['id'], $existing_ids, true ) ) {
			throw new ZencommunityException( esc_html( __( "Menu ID is already exists.", 'zencommunity' ) ), 422 );
		}

		// Default icon fallback
		$item['icon'] = $item['icon'] ?? [
			'type' => 'emoji',
			'src'  => '🔗',
		];

		$all_menus[ $this->menu_key ]['items'][] = $item;
		update_option( self::BASE_OPTION_KEY, $all_menus );
		return $this->find_item( $item['id'] );
	}

	public function update_link_item( string $item_id, array $new_data ) : array {
		$all_menus = get_option( self::BASE_OPTION_KEY, [] );
		if ( empty( $all_menus[ $this->menu_key ]['items'] ) ) {
			throw new ZencommunityException( esc_html( __( "Menu is not exists.", 'zencommunity' ) ), 422 );
		}

		foreach ( $all_menus[ $this->menu_key ]['items'] as &$item ) {
			if (
				( $item['id'] ?? '' ) === $item_id &&
				( $item['type'] ?? '' ) === 'link'
			) {
				foreach ( $new_data as $key => $value ) {
					if ( $key !== 'id' && $key !== 'type' ) {
						$item[ $key ] = $value;
					}

					if ( 'roles' === $key && empty( $new_data[ $key ] ) ) {
						$item[ $key ] = null;
					}
				}
				update_option( self::BASE_OPTION_KEY, $all_menus );
				return $this->find_item( $item_id );
			}
		}
		throw new ZencommunityException( esc_html( __( "Unknown error.", 'zencommunity' ) ), 422 );
	}

	public function delete_link_item( string $item_id ) : bool {
		$all_menus = get_option( self::BASE_OPTION_KEY, [] );
		if ( empty( $all_menus[ $this->menu_key ]['items'] ) ) {
			throw new ZencommunityException( esc_html( __( "Menu is not exists.", 'zencommunity' ) ), 422 );
		}

		$found = false;
		foreach ( $all_menus[ $this->menu_key ]['items'] as $index => $item ) {
			if (
				( $item['id'] ?? '' ) === $item_id &&
				( $item['type'] ?? '' ) === 'link'
			) {
				unset( $all_menus[ $this->menu_key ]['items'][ $index ] );
				$found = true;
				break;
			}
		}

		if ( $found ) {
			$all_menus[ $this->menu_key ]['items'] = array_values( $all_menus[ $this->menu_key ]['items'] );
			return update_option( self::BASE_OPTION_KEY, $all_menus );
		}
		throw new ZencommunityException( esc_html( __( "Menu id not found.", 'zencommunity' ) ), 422 );
	}
}
